'use client'

import {
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type ReactNode,
} from 'react'
import { SplitWordLoaderEngine, splitWordLoaderTiming } from './split-word-loader.engine'

export interface SplitWordLoaderOptions {
  word: string
  splitAt: number
  durationScale: number
  progress: number
  playKey: number
  background: string
  color: string
  fontSize: number
  fontWeight: number
  letterSpacing: number
  fontFamily: string
  imageRatio: number
  fixed: boolean
  label: string
}

export interface SplitWordLoaderProps extends Partial<SplitWordLoaderOptions> {
  images?: string[]
  onComplete?: () => void
  className?: string
  style?: CSSProperties
  children?: ReactNode
}

export const splitWordLoaderDefaults: SplitWordLoaderOptions = {
  word: 'GROVE',
  splitAt: 0,
  durationScale: 1,
  progress: 1,
  playKey: 0,
  background: '#e7e7e7',
  color: '#1c1a1b',
  fontSize: 14,
  fontWeight: 500,
  letterSpacing: -0.03,
  fontFamily: 'inherit',
  imageRatio: 1.41,
  fixed: false,
  label: 'Loading',
}

const MOTION_QUERY = '(prefers-reduced-motion: reduce)'
const MAX_DT = 0.1
const EDGE = '-9999px'

function subscribeMotion(onChange: () => void) {
  const query = window.matchMedia(MOTION_QUERY)
  query.addEventListener('change', onChange)
  return () => query.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

function splitWord(word: string, splitAt: number) {
  const letters = Array.from(word)
  const auto = Math.floor(letters.length / 2)
  const at = splitAt > 0 ? Math.min(Math.round(splitAt), letters.length) : auto
  return { letters, left: letters.slice(0, at), right: letters.slice(at) }
}

const EMPTY: string[] = []

export function SplitWordLoader({
  word = splitWordLoaderDefaults.word,
  splitAt = splitWordLoaderDefaults.splitAt,
  durationScale = splitWordLoaderDefaults.durationScale,
  progress = splitWordLoaderDefaults.progress,
  playKey = splitWordLoaderDefaults.playKey,
  background = splitWordLoaderDefaults.background,
  color = splitWordLoaderDefaults.color,
  fontSize = splitWordLoaderDefaults.fontSize,
  fontWeight = splitWordLoaderDefaults.fontWeight,
  letterSpacing = splitWordLoaderDefaults.letterSpacing,
  fontFamily = splitWordLoaderDefaults.fontFamily,
  imageRatio = splitWordLoaderDefaults.imageRatio,
  fixed = splitWordLoaderDefaults.fixed,
  label = splitWordLoaderDefaults.label,
  images = EMPTY,
  onComplete,
  className,
  style,
  children,
}: SplitWordLoaderProps) {
  const reduced = useReducedMotion()
  const [run, setRun] = useState({ key: playKey, stage: 0, percent: 0 })
  // A new play key restarts the loader from the top
  if (run.key !== playKey) setRun({ key: playKey, stage: 0, percent: 0 })
  const stage = run.key === playKey ? run.stage : 0

  const overlayRef = useRef<HTMLDivElement>(null)
  const rowRef = useRef<HTMLDivElement>(null)
  const leftRef = useRef<HTMLDivElement>(null)
  const rightRef = useRef<HTMLDivElement>(null)
  const slotRef = useRef<HTMLSpanElement>(null)
  const boxRef = useRef<HTMLDivElement>(null)
  const progressRef = useRef(progress)
  const completeRef = useRef(onComplete)
  const measureRef = useRef(true)

  useEffect(() => {
    progressRef.current = progress
    completeRef.current = onComplete
  }, [progress, onComplete])

  const { letters, left, right } = splitWord(word, splitAt)
  const letterCount = letters.length
  const imageCount = images.length

  useEffect(() => {
    measureRef.current = true
  }, [word, splitAt, fontSize, fontWeight, letterSpacing, fontFamily])

  useEffect(() => {
    const overlay = overlayRef.current
    const row = rowRef.current
    const slot = slotRef.current
    const box = boxRef.current
    const groups = [leftRef.current, rightRef.current].filter(
      (group): group is HTMLDivElement => group !== null,
    )
    if (!overlay || !row || !slot || !box) return
    const glyphs = groups.flatMap((group) => Array.from(group.children) as HTMLElement[])
    const pictures = Array.from(box.children) as HTMLElement[]
    const engine = new SplitWordLoaderEngine({
      letters: letterCount,
      images: imageCount,
      durationScale,
      imageRatio,
      reduced,
    })
    const layout = { width: 0, height: 0, cap: 0 }
    let clipBottom = 0
    let raf = 0
    let last = 0
    let visible = true
    let stageNow = 0
    let percent = -1
    let shown = -2
    let drawn = -1

    const measure = () => {
      measureRef.current = false
      const frameRect = overlay.getBoundingClientRect()
      const rowRect = row.getBoundingClientRect()
      const slotRect = slot.getBoundingClientRect()
      const groupRect = (
        groups.find((group) => group.childElementCount > 0) ?? row
      ).getBoundingClientRect()
      layout.width = frameRect.width
      layout.height = frameRect.height
      layout.cap = slotRect.height
      clipBottom =
        groupRect.bottom - slotRect.bottom - layout.cap * splitWordLoaderTiming.clipOvershoot
      const slotCenter = slotRect.top - rowRect.top + slotRect.height / 2
      row.style.transform = `translate3d(0, ${rowRect.height / 2 - slotCenter}px, 0)`
      row.style.visibility = 'visible'
    }

    const apply = () => {
      // A held clock with an unchanged layout needs no writes
      if (engine.time === drawn && !measureRef.current) return false
      if (measureRef.current) measure()
      drawn = engine.time
      const frame = engine.frame(layout)
      frame.letters.forEach((offset, i) => {
        const glyph = glyphs[i]
        if (glyph) glyph.style.transform = `translate3d(0, ${offset}px, 0)`
      })
      const clip = frame.masked ? `inset(${EDGE} ${EDGE} ${clipBottom}px ${EDGE})` : 'none'
      for (const group of groups) group.style.clipPath = clip
      slot.style.width = `${frame.slot}px`
      if (frame.boxWidth < 0.5 || frame.boxHeight < 0.5) box.style.visibility = 'hidden'
      else {
        box.style.visibility = 'visible'
        box.style.width = `${frame.boxWidth}px`
        box.style.height = `${frame.boxHeight}px`
        box.style.left = `${(layout.width - frame.boxWidth) / 2}px`
        box.style.top = `${(layout.height - frame.boxHeight) / 2}px`
      }
      if (frame.image !== shown) {
        shown = frame.image
        pictures.forEach((picture, i) => {
          picture.style.opacity = i === shown ? '1' : '0'
        })
      }
      overlay.style.opacity = `${frame.opacity}`
      const loaded = Math.min(frame.progress, progressRef.current)
      const step = Math.floor(loaded * 4) * 25
      const next = frame.finished ? 2 : frame.revealed ? 1 : 0
      if (step !== percent || next !== stageNow) {
        percent = step
        if (next === 1 && stageNow === 0) completeRef.current?.()
        stageNow = next
        setRun((state) =>
          state.key === playKey ? { key: playKey, stage: next, percent: step } : state,
        )
      }
      return frame.finished
    }

    const tick = (now: number) => {
      raf = 0
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 0
      last = now
      engine.advance(dt, progressRef.current)
      if (!apply() && visible) raf = requestAnimationFrame(tick)
    }

    const start = () => {
      if (raf || engine.finished) return
      last = 0
      raf = requestAnimationFrame(tick)
    }

    const stop = () => {
      if (raf) cancelAnimationFrame(raf)
      raf = 0
    }

    measureRef.current = true
    apply()
    start()

    const resize = new ResizeObserver(() => {
      measureRef.current = true
      if (!raf && !engine.finished) apply()
    })
    resize.observe(overlay)
    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      if (visible) start()
      else stop()
    })
    intersection.observe(overlay)
    const onFonts = () => {
      measureRef.current = true
    }
    document.fonts?.addEventListener('loadingdone', onFonts)
    void document.fonts?.ready.then(onFonts)

    return () => {
      stop()
      resize.disconnect()
      intersection.disconnect()
      document.fonts?.removeEventListener('loadingdone', onFonts)
    }
  }, [playKey, reduced, letterCount, imageCount, durationScale, imageRatio])

  const state = stage === 0 ? 'loading' : stage === 1 ? 'revealing' : 'done'

  return (
    <div
      className={['uig-split-word-loader', 'isolate', className].filter(Boolean).join(' ')}
      style={style}
      data-state={state}
    >
      <div className="uig-split-word-loader__content" inert={stage === 0}>
        {children}
      </div>
      {stage < 2 && (
        <div
          key={playKey}
          ref={overlayRef}
          role="status"
          className="uig-split-word-loader__overlay inset-0 z-10 flex items-center justify-center overflow-hidden [container-type:size]"
          style={{
            position: fixed ? 'fixed' : 'absolute',
            background,
            color,
            pointerEvents: stage === 1 ? 'none' : undefined,
          }}
        >
          <span className="uig-split-word-loader__status sr-only">{`${label} ${run.percent}%`}</span>
          <div
            ref={rowRef}
            aria-hidden="true"
            className="uig-split-word-loader__row invisible flex w-full shrink-0 items-baseline whitespace-pre"
            style={{
              fontFamily,
              fontWeight,
              fontSize: `${fontSize}cqw`,
              letterSpacing: `${letterSpacing}em`,
              lineHeight: 1,
            }}
          >
            <div
              ref={leftRef}
              className="uig-split-word-loader__left flex min-w-0 flex-1 items-baseline justify-end"
            >
              {left.map((letter, i) => (
                <span key={i} className="uig-split-word-loader__letter block will-change-transform">
                  {letter}
                </span>
              ))}
            </div>
            <span
              ref={slotRef}
              className="uig-split-word-loader__slot block h-[1cap] w-0 shrink-0"
            />
            <div
              ref={rightRef}
              className="uig-split-word-loader__right flex min-w-0 flex-1 items-baseline justify-start"
            >
              {right.map((letter, i) => (
                <span key={i} className="uig-split-word-loader__letter block will-change-transform">
                  {letter}
                </span>
              ))}
            </div>
          </div>
          <div
            ref={boxRef}
            aria-hidden="true"
            className="uig-split-word-loader__box invisible absolute top-0 left-0 overflow-hidden bg-current"
          >
            {images.map((src, i) => (
              <img
                key={`${src}-${i}`}
                src={src}
                alt=""
                decoding="async"
                draggable={false}
                className="uig-split-word-loader__image absolute inset-0 h-full w-full object-cover opacity-0"
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

export interface SplitWordLoaderTiming {
  rise: number
  stagger: number
  riseDistance: number
  openAt: number
  open: number
  firstCut: number
  interval: number
  lastHold: number
  expand: number
  fade: number
  slotRatio: number
  clipOvershoot: number
}

export interface SplitWordLoaderEngineOptions {
  letters: number
  images: number
  durationScale: number
  imageRatio: number
  reduced: boolean
}

export interface SplitWordLoaderLayout {
  width: number
  height: number
  cap: number
}

export interface SplitWordLoaderTimeline {
  riseEnd: number
  openStart: number
  openEnd: number
  appear: number[]
  expandStart: number
  expandEnd: number
  end: number
}

export interface SplitWordLoaderFrame {
  letters: number[]
  masked: boolean
  slot: number
  boxWidth: number
  boxHeight: number
  image: number
  opacity: number
  progress: number
  revealed: boolean
  finished: boolean
}

// Timeline in seconds, distances in multiples of cap height
export const splitWordLoaderTiming: SplitWordLoaderTiming = {
  rise: 0.613,
  stagger: 0.018,
  riseDistance: 1.056,
  openAt: 0.947,
  open: 0.605,
  firstCut: 0.75,
  interval: 0.36,
  lastHold: 0.44,
  expand: 0.965,
  fade: 0.35,
  slotRatio: 1.1,
  clipOvershoot: 0.02,
}

export const splitWordLoaderBezier = [0.76, 0, 0.24, 1] as const

export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const cx = 3 * x1
  const bx = 3 * (x2 - x1) - cx
  const ax = 1 - cx - bx
  const cy = 3 * y1
  const by = 3 * (y2 - y1) - cy
  const ay = 1 - cy - by
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s
  const slopeX = (s: number) => (3 * ax * s + 2 * bx) * s + cx
  return (x: number) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    let s = x
    for (let i = 0; i < 8; i++) {
      const error = sampleX(s) - x
      if (Math.abs(error) < 1e-6) return sampleY(s)
      const slope = slopeX(s)
      if (Math.abs(slope) < 1e-6) break
      s -= error / slope
    }
    let lo = 0
    let hi = 1
    s = x
    while (hi - lo > 1e-6) {
      if (sampleX(s) < x) lo = s
      else hi = s
      s = (lo + hi) / 2
    }
    return sampleY(s)
  }
}

export const splitWordLoaderEase = cubicBezier(...splitWordLoaderBezier)

function clamp01(value: number) {
  return value < 0 ? 0 : value > 1 ? 1 : value
}

export function splitWordLoaderTimeline(
  options: SplitWordLoaderEngineOptions,
  timing: SplitWordLoaderTiming = splitWordLoaderTiming,
): SplitWordLoaderTimeline {
  const k = Math.max(options.durationScale, 0.05)
  if (options.reduced) {
    return {
      riseEnd: 0,
      openStart: 0,
      openEnd: 0,
      appear: [],
      expandStart: 0,
      expandEnd: 0,
      end: timing.fade * k,
    }
  }
  const riseEnd = (timing.rise + timing.stagger * Math.max(options.letters - 1, 0)) * k
  const openStart = timing.openAt * k
  const openEnd = openStart + timing.open * k
  const appear: number[] = []
  for (let i = 0; i < options.images; i++) {
    appear.push(i === 0 ? openStart : openStart + (timing.firstCut + (i - 1) * timing.interval) * k)
  }
  const last = appear[appear.length - 1] ?? openStart
  const expandStart = Math.max(last, openEnd) + timing.lastHold * k
  const expandEnd = expandStart + timing.expand * k
  return {
    riseEnd,
    openStart,
    openEnd,
    appear,
    expandStart,
    expandEnd,
    end: expandEnd + timing.fade * k,
  }
}

export class SplitWordLoaderEngine {
  time = 0
  timeline: SplitWordLoaderTimeline
  private options: SplitWordLoaderEngineOptions
  private timing: SplitWordLoaderTiming

  constructor(
    options: SplitWordLoaderEngineOptions,
    timing: SplitWordLoaderTiming = splitWordLoaderTiming,
  ) {
    this.options = options
    this.timing = timing
    this.timeline = splitWordLoaderTimeline(options, timing)
  }

  reset() {
    this.time = 0
  }

  // Latest time the clock may reach while assets are still loading
  gate(progress: number) {
    if (progress >= 1) return Infinity
    const { openEnd, expandStart } = this.timeline
    return openEnd + clamp01(progress) * (expandStart - openEnd)
  }

  advance(dt: number, progress = 1) {
    const limit = this.gate(progress)
    this.time = Math.min(this.time + dt, Math.max(this.time, limit))
  }

  get finished() {
    return this.time >= this.timeline.end
  }

  frame(layout: SplitWordLoaderLayout, time = this.time): SplitWordLoaderFrame {
    const { letters, imageRatio, durationScale } = this.options
    const timing = this.timing
    const line = this.timeline
    const k = Math.max(durationScale, 0.05)
    const ease = splitWordLoaderEase
    const offsets: number[] = []
    for (let i = 0; i < letters; i++) {
      const p = this.options.reduced
        ? 1
        : clamp01((time - i * timing.stagger * k) / (timing.rise * k))
      offsets.push(timing.riseDistance * layout.cap * (1 - ease(p)))
    }
    const reduced = this.options.reduced
    const open = reduced
      ? 0
      : ease(clamp01((time - line.openStart) / (line.openEnd - line.openStart)))
    const grow = reduced
      ? 0
      : ease(clamp01((time - line.expandStart) / (line.expandEnd - line.expandStart)))
    const base = imageRatio * layout.cap * open
    const boxWidth = base + (layout.width - base) * grow
    const boxHeight = open > 0 ? layout.cap + (layout.height - layout.cap) * grow : 0
    let image = -1
    for (let i = 0; i < line.appear.length; i++) {
      const at = line.appear[i]
      if (at !== undefined && time >= at) image = i
    }
    return {
      letters: offsets,
      masked: time < line.riseEnd,
      slot: boxWidth * timing.slotRatio,
      boxWidth,
      boxHeight,
      image,
      opacity: 1 - clamp01((time - line.expandEnd) / (line.end - line.expandEnd)),
      progress: line.expandEnd > 0 ? clamp01(time / line.expandEnd) : 1,
      revealed: time >= line.expandEnd,
      finished: time >= line.end,
    }
  }
}
